import time
import urllib.request
import urllib.error


class RateLimitError(Exception):
    """Raised when the API keeps returning HTTP 429 after retries."""
    pass


class ServerError(Exception):
    """Raised when the API keeps returning HTTP 5xx after retries."""
    pass


class ClientError(Exception):
    """Raised when the API returns an HTTP 4xx (other than 429)."""
    pass


class ConnectionError(Exception):
    """Raised when a network error persists after retries."""
    pass


class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path

        # Rate-limit (429): up to 3 retries with exponential backoff.
        backoffs_429 = [0.5, 1.0, 2.0]
        # Server errors (5xx): 1 retry after 1s.
        backoffs_5xx = [1.0]
        # Network errors: 1 retry after 1s.
        backoffs_net = [1.0]

        attempt_429 = 0
        attempt_5xx = 0
        attempt_net = 0

        while True:
            try:
                with urllib.request.urlopen(url, timeout=self.timeout) as response:
                    return response.read().decode("utf-8")

            except urllib.error.HTTPError as exc:
                status = exc.code

                if status == 429:
                    if attempt_429 < len(backoffs_429):
                        time.sleep(backoffs_429[attempt_429])
                        attempt_429 += 1
                        continue
                    raise RateLimitError(
                        "Rate limited (429) after {} retries: {}".format(attempt_429, url)
                    ) from exc

                elif 500 <= status < 600:
                    if attempt_5xx < len(backoffs_5xx):
                        time.sleep(backoffs_5xx[attempt_5xx])
                        attempt_5xx += 1
                        continue
                    raise ServerError(
                        "Server error ({}) after {} retry: {}".format(status, attempt_5xx, url)
                    ) from exc

                else:
                    raise ClientError(
                        "Client error ({}): {}".format(status, url)
                    ) from exc

            except urllib.error.URLError as exc:
                if attempt_net < len(backoffs_net):
                    time.sleep(backoffs_net[attempt_net])
                    attempt_net += 1
                    continue
                raise ConnectionError(
                    "Connection failed after {} retry: {}".format(attempt_net, url)
                ) from exc
